                unsafe highwayLoadInterleaved2U8(from: source.baseAddress!, &r0, &r1)
            }
            mismatches.check(p0, r0, "from: \(describe(from)), v0")
            mismatches.check(p1, r1, "from: \(describe(from)), v1")
        }
        mismatches.record()
    }

