    @Test func maskedLowercaseSpan() {
        let mismatches = Mismatches("portMaskedLowercaseSpanU8")
        let spanInputs = Inputs.byteBuffers(count: 3 * H.laneCount + 1, seed: 0x42E9_4F02_1DE3_87EA)
        let spanCountInputs = Inputs.counts(through: 3 * H.laneCount + 1)
        for (span, spanCount) in everyPair(spanInputs, spanCountInputs) {
            let spanPrefix = ContiguousArray(span.prefix(spanCount))
            let (portResult, portLanes) = withOutputSpan(capacity: spanPrefix.count) { output in
                portMaskedLowercaseSpanU8(span: spanPrefix.span, into: &output)
            }
            let (referenceResult, referenceLanes) = withOutputSpan(capacity: spanPrefix.count) {
                output in
                highwayMaskedLowercaseSpanU8(span: spanPrefix.span, into: &output)
            }
            mismatches.check(
                portResult,
                referenceResult,
                "span: \(describe(span)), spanCount: \(spanCount)"
            )
            mismatches.check(
                portLanes,
                referenceLanes,
                "span: \(describe(span)), spanCount: \(spanCount)"
            )
        }
        mismatches.record()
    }

